bool Sudoku::isValid(int row, int col, int num) const
{
	for (int x = 0; x < N; ++x)
	{
		if (solution_[row][x] == num)
			return false;

		if (solution_[x][col] == num)
			return false;
	}

	int startRow = row - row % 3;
	int startCol = col - col % 3;

	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
			if (solution_[startRow + i][startCol + j] == num)
				return false;

	return true;
}

bool Sudoku::findEmpty(int& row, int& col) const
{
	for (row = 0; row < N; ++row)
		for (col = 0; col < N; ++col)
			if (solution_[row][col] == 0)
				return true;

	return false;
}

bool Sudoku::solveRecursive(Grid& grid)
{
	int row, col;

	if (!findEmpty(row, col))
		return true;

	for (int num = 1; num <= 9; ++num)
	{
		if (isValid(row, col, num))
		{
			grid[row][col] = num;
			solution_[row][col] = num;

			if (solveRecursive(grid))
				return true;

			grid[row][col] = 0;
			solution_[row][col] = 0;
		}
	}

	return false;
}

