		}

		std::cout << "| ";

		for (int c = 0; c < N; ++c)
		{
			if (c % 3 == 0 && c != 0)
			{
				std::cout << "| ";
			}

			if (grid[r][c] == 0)
			{
				std::cout << ". ";
			}
			else
			{
				std::cout << grid[r][c] << " ";
			}
		}

		std::cout << "|\n";
	}
	std::cout << "+-------+-------+-------+\n";
}

bool Sudoku::_isValid(int row, int col, int num) const
{
	for (int x = 0; x < N; ++x)
	{
		if (_solution[row][x] == num)
			return false;

		if (_solution[x][col] == num)
			return false;
	}

	int startRow = row - row % 3;
	int startCol = col - col % 3;

	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
			if (_solution[startRow + i][startCol + j] == num)
				return false;

	return true;
}

bool Sudoku::_solveRecursive(Grid& grid, int row, int col)
{
	// Find next empty cell starting from (row, col)
	while (row < N && grid[row][col] != 0)
	{
		++col;

		if (col == N)
		{
			col = 0;
			++row;
		}
	}

	// No empty cells left - solved
	if (row == N)
		return true;

	for (int num = 1; num <= 9; ++num)
	{
		if (_isValid(row, col, num))
		{
			grid[row][col] = num;
			_solution[row][col] = num;

			if (_solveRecursive(grid, row, col))
				return true;

			grid[row][col] = 0;
			_solution[row][col] = 0;
		}
	}

	return false;
}

