	auto processHouse = [&](auto getCells) -> bool {
		bool local_progress = false;
		for (int d = 1; d <= 9; ++d) {
			Mask pair_mask = DIGIT_MASK[d];
			// Find cells with exactly 2 candidates
			// This is simplified - full implementation would check all pairs
		}
		return local_progress;
	};

	// Simplified: skip for now, but structure is ready
	// Full naked pairs/triples implementation would go here
	return progress;
}

// Locked candidates (pointing pairs, box-line reduction)
bool Sudoku::_lockedCandidates()
{
	bool progress = false;

	// Box-line reduction: if a digit in a box is confined to one row/col,
	// eliminate it from rest of that row/col outside the box
	for (int b = 0; b < 9; ++b) {
		for (int d = 1; d <= 9; ++d) {
			Mask m = DIGIT_MASK[d];
			if (_boxes[b] & m) continue;

			// Find all cells in box with this candidate
			int rows_mask = 0, cols_mask = 0;
			int count = 0;
			for (int i = 0; i < 81; ++i) {
				if (BOX_OF[i] == b && _cell_candidates[i] & m) {
					int r = i / 9, c = i % 9;
					rows_mask |= 1 << r;
					cols_mask |= 1 << c;
					count++;
				}
			}

			// If all in same row, eliminate from rest of row
			if (count > 1 && (rows_mask & (rows_mask - 1)) == 0) {
				int r = __builtin_ctz(rows_mask);
				for (int c = 0; c < N; ++c) {
					if (BOX_OF[r * 9 + c] != b && _solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
						_cell_candidates[r * 9 + c] &= ~m;
						progress = true;
					}
				}
			}

			// If all in same col, eliminate from rest of col
			if (count > 1 && (cols_mask & (cols_mask - 1)) == 0) {
				int c = __builtin_ctz(cols_mask);
				for (int r = 0; r < N; ++r) {
					if (BOX_OF[r * 9 + c] != b && _solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
						_cell_candidates[r * 9 + c] &= ~m;
						progress = true;
					}
				}
			}
		}
	}

	return progress;
}

bool Sudoku::_solveRecursive()
{
	int cell = _findBestCell();
	if (cell == -1) return true; // solved

	int row = cell / 9;
	int col = cell % 9;
	Mask candidates = _cell_candidates[cell];
	int b = BOX_OF[cell];

	// Try each candidate (least constraining value heuristic could be added)
	while (candidates) {
		Mask m = candidates & -candidates; // isolate lowest bit
		int num = __builtin_ctz(m); // get digit (1-9)
		candidates &= candidates - 1; // clear lowest bit

		// Place digit
		_solution[row][col] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

		// Save affected candidates for restoration
		Mask saved_candidates[20];
		int saved_count = 0;
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				if (_solution[r][c] == 0 && (_cell_candidates[r * 9 + c] & m)) {
					saved_candidates[saved_count++] = _cell_candidates[r * 9 + c];
					_cell_candidates[r * 9 + c] &= ~m;
				}
			}
		}

		if (_solveRecursive())
			return true;

		// Backtrack
		_solution[row][col] = 0;
		_rows[row] &= ~m;
		_cols[col] &= ~m;
		_boxes[b] &= ~m;

		// Restore candidates
		int idx = 0;
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				if (_solution[r][c] == 0 && (saved_candidates[idx] != _cell_candidates[r * 9 + c])) {
					_cell_candidates[r * 9 + c] = saved_candidates[idx++];
				}
			}
		}
	}

	return false;
}

// Bit-packed grid utilities
Sudoku::PackedGrid Sudoku::packGrid(const Grid& grid)
{
	PackedGrid packed = {};
	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			int idx = r * 9 + c;
			int bit_pos = idx * 4;
			int word = bit_pos / 64;
			int shift = bit_pos % 64;
			packed[word] |= (static_cast<uint64_t>(grid[r][c]) << shift);
		}
	}
	return packed;
}

Sudoku::Grid Sudoku::unpackGrid(const PackedGrid& packed)
{
	Grid grid = {};
	for (int r = 0; r < N; ++r) {
		for (int c = 0; c < N; ++c) {
			int idx = r * 9 + c;
			int bit_pos = idx * 4;
			int word = bit_pos / 64;
			int shift = bit_pos % 64;
			grid[r][c] = static_cast<int>((packed[word] >> shift) & 0xF);
		}
	}
	return grid;
}

