using Grid = Sudoku::Grid;
using Clock = std::chrono::high_resolution_clock;

template<typename Solver>
void benchmark(const char* name, const Grid& puzzle, Grid& solution)
{
	auto start = Clock::now();
	bool solved = Solver::solve(puzzle, solution);
	auto end = Clock::now();
	auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

	std::cout << name << ": ";
	if (solved) {
		std::cout << "SOLVED in " << duration.count() << " µs\n";
	} else {
		std::cout << "FAILED\n";
	}
}

int main()
{
	Grid puzzle = Sudoku::EXAMPLE_PUZZLE;
	Grid solution;

	std::cout << "=== Sudoku Solver Benchmark ===\n\n";

	std::cout << "START SUDOKU:\n";
	Sudoku sudoku(puzzle);
	sudoku.Draw(true);
	std::cout << "\n";

	// Test bitmask + MRV + propagation solver
	{
		Grid sol;
		Sudoku s(puzzle);
		s.solve();
		sol = s.getSolution();
		std::cout << "Bitmask + MRV + Propagation:\n";
		s.Draw(false);
	}

	std::cout << "\n---\n";

	// Test DLX solver
	{
		Grid sol;
		benchmark("DLX (Algorithm X)", puzzle, sol);
		if (SudokuDLX::validate(sol)) {
			std::cout << "DLX Solution:\n";
			for (int r = 0; r < 9; ++r) {
				for (int c = 0; c < 9; ++c) {
					std::cout << sol[r][c] << ' ';
				}
				std::cout << '\n';
			}
		}
	}

	std::cout << "\n---\n";

	// Benchmark multiple runs
	std::cout << "\n=== Performance Test (100 iterations) ===\n";

	// Hard puzzle (AI Escargot)
	Grid hard_puzzle = {{
		{1, 0, 0, 0, 0, 7, 0, 9, 0},
		{0, 3, 0, 0, 2, 0, 0, 0, 8},
