}

void SudokuDLX::decodeSolution(const std::vector<int>& solution_rows, Grid& solution)
{
	solution.fill(0);
	for (int row_id : solution_rows) {
		int r = row_id / 81;
		int c = (row_id % 81) / 9;
		int d = (row_id % 9) + 1;
		solution[idx(r, c)] = d;
	}
}

bool SudokuDLX::validate(const Grid& grid)
{
	// Check rows
	for (int r = 0; r < 9; ++r) {
		uint16_t seen = 0;
		for (int c = 0; c < 9; ++c) {
			int v = grid[idx(r, c)];
			if (v < 1 || v > 9) return false;
			if (seen & (1 << v)) return false;
			seen |= 1 << v;
		}
	}

	// Check columns
	for (int c = 0; c < 9; ++c) {
		uint16_t seen = 0;
		for (int r = 0; r < 9; ++r) {
			int v = grid[idx(r, c)];
			if (seen & (1 << v)) return false;
			seen |= 1 << v;
		}
	}

	// Check boxes
	for (int br = 0; br < 3; ++br) {
		for (int bc = 0; bc < 3; ++bc) {
			uint16_t seen = 0;
			for (int r = 0; r < 3; ++r) {
				for (int c = 0; c < 3; ++c) {
					int v = grid[idx(br * 3 + r, bc * 3 + c)];
					if (seen & (1 << v)) return false;
					seen |= 1 << v;
				}
			}
		}
	}

	return true;
}

