	while (candidates) {
		Mask m = candidates & -candidates;
		int num = __builtin_ctz(m);
		candidates &= candidates - 1;

		// Place digit
		_solution[cell] = num;
		_rows[row] |= m;
		_cols[col] |= m;
		_boxes[b] |= m;

