#else
#define SUDOKU_AVX2 0
#endif

using Mask = Sudoku::Mask;

// Portable popcount
inline int popcount(Mask m)
{
#if defined(_MSC_VER)
    return __popcnt(static_cast<unsigned int>(m));
#else
    return __builtin_popcount(static_cast<unsigned int>(m));
#endif
