bool Sudoku::_nakedSingles()
{
	bool progress = false;
	for (int i = 0; i < 81; ++i) {
		if (_solution[i] == 0) {
			Mask candidates = _cell_candidates[i];
			if (candidates && (candidates & (candidates - 1)) == 0) {
				int num = ctz(candidates);
				int r = i / 9, c = i % 9;
				_solution[i] = num;
				Mask m = DIGIT_MASK[num];
				_rows[r] |= m;
				_cols[c] |= m;
				_boxes[BOX_OF[i]] |= m;
				_cell_candidates[i] = 0;
				progress = true;
			}
		}
	}
	if (progress) {
		for (int r = 0; r < N; ++r) {
			for (int c = 0; c < N; ++c) {
				_updateCandidates(r, c);
			}
		}
	}
	return progress;
}

