9	template<typename Solver>
10	void benchmark(const char* name, const Grid& puzzle, Grid& solution)
11	{
12		auto start = Clock::now();
13		bool solved = Solver::solve(puzzle, solution);
14		auto end = Clock::now();
15		auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
